// orders.js - one module per table
export const overdueOrders = (db, asOf) =>
  db('orders').where('due', '<', asOf).select('id', 'due', 'total');

export const totalOf = (rows) => rows.reduce((sum, row) => sum + row.total, 0);

export const flagOverdue = (db, asOf) =>        // set-oriented write, no row loop
  db('orders').where('due', '<', asOf).update({ flagged: true });
